using System.ComponentModel.DataAnnotations;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Logistica_y_transporte.Seguridad;
namespace Logistica_y_transporte.Areas.Identity.Pages.Account;
[Authorize] public class CambiarTemporalModel(UserManager<IdentityUser> users,SignInManager<IdentityUser> signIn):PageModel{
 [BindProperty] public Entrada Input{get;set;}=new();public class Entrada{[Required,MaxLength(128),DataType(DataType.Password)]public string Actual{get;set;}="";[Required,StringLength(128,MinimumLength=8),DataType(DataType.Password)]public string Nueva{get;set;}="";[Required,MaxLength(128),Compare(nameof(Nueva)),DataType(DataType.Password)]public string Confirmacion{get;set;}="";}
 public async Task<IActionResult> OnGetAsync(){var u=await users.GetUserAsync(User);if(u is null)return Challenge();return (await users.GetClaimsAsync(u)).Any(c=>c.Type==AccesosIniciales.Temporal)?Page():LocalRedirect(Url.Content("~/Identity/Account/Manage"));}
 public async Task<IActionResult> OnPostAsync(){if(!ModelState.IsValid)return Page();var u=await users.GetUserAsync(User);if(u is null)return Challenge();if(await users.IsLockedOutAsync(u)){ModelState.AddModelError("", "Demasiados intentos. Espera 15 minutos. / Too many attempts. Wait 15 minutes.");return Page();}if(Input.Actual==Input.Nueva){ModelState.AddModelError("","Elige una contraseña diferente. / Choose a different password.");return Page();}
 var result=await users.ChangePasswordAsync(u,Input.Actual,Input.Nueva);if(!result.Succeeded){if(result.Errors.Any(e=>e.Code=="PasswordMismatch"))await users.AccessFailedAsync(u);ModelState.AddModelError("","Revisa tu contraseña temporal y los cinco requisitos. / Check your temporary password and all five requirements.");return Page();}
 foreach(var claim in (await users.GetClaimsAsync(u)).Where(c=>c.Type==AccesosIniciales.Temporal)){if(!(await users.RemoveClaimAsync(u,claim)).Succeeded){ModelState.AddModelError("","La clave cambió, pero no se pudo finalizar el acceso temporal. Vuelve a intentarlo con tu nueva contraseña. / Password changed, but temporary access could not be finalized. Retry with your new password.");return Page();}}await users.ResetAccessFailedCountAsync(u);await users.UpdateSecurityStampAsync(u);await signIn.SignOutAsync();return LocalRedirect(Url.Content("~/Identity/Account/Login"));
 }}
